/**
 * One cell of the compact facts line (spec/10 §4.1): [text] is the caller's claim word („Keine Tracker“), [refs] the
 * fact refs whose notes back it, one note per ref („tracking.trackers“; the network level „verbindet sich mit keinem
 * Server“ names every never-path to a remote place). [place] = a remote place „Helsinki (FI)“ with the pin before it.
 */
@Immutable
data class SbFactCell(val text: String, val refs: List<String> = emptyList(), val place: Boolean = false)

/**
 * The compact form (a) of the facts (spec/10 §4.1): the product name, then each cell after a „·“, caption textMuted,
 * wrapping between cells. A cell shows only when every ref has a note that may state it (D21); the others are counted
 * into „n nicht belegt“, a link-style button when [onHidden] leads to the full form. Stale: the name, the stale
 * notice, the demo marker. The demo marker last. Once a cell with its „·“ no longer fits one line (large text,
 * D101 (11), (12)), the line becomes a list: the name on its own line, under it each cell on its own line, no „·“,
 * the same type and colours. The gutter at the sides; one TalkBack node, the button its own. It chooses the form
 * from its width (a BoxWithConstraints), so it cannot stand in a parent that asks for intrinsic sizes (spec/08 §17).
 */
@Composable
fun SbFactsLine(
    notes: SbNotes,
    cells: List<SbFactCell>,
    todayIso: String,
    modifier: Modifier = Modifier,
    onHidden: (() -> Unit)? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val stale = notes.isStale(todayIso)
    val shown = if (stale) emptyList() else cells.filter { cell -> cell.refs.all { notes.note(it)?.showsClaim == true } }
    val hidden = if (stale) 0 else cells.size - shown.size
    val hiddenWord = if (hidden > 0) sbMessages().factsHidden(sbFormatCount(hidden)) else null
    val measurer = rememberTextMeasurer()
    val name: @Composable (Modifier) -> Unit = { place ->
        Text(notes.productName, style = ty.caption.copy(fontWeight = ty.label.fontWeight), color = c.text, modifier = place)
    }
    val staleCell: @Composable () -> Unit = {
        Row(horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
            Icon(
                SebaroIcons.Filled16.Warning,
                contentDescription = null,
                tint = c.warning,
                modifier = Modifier.padding(top = t.space.s0_5).size(t.size.iconSm),
            )
            Text(notes.staleNotice ?: "", style = ty.caption, color = c.text)
        }
    }
    val factCell: @Composable (SbFactCell) -> Unit = { cell ->
        if (cell.place) {
            Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s0_5)) {
                Icon(SebaroIcons.Outline16.Pin, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconSm))
                Text(cell.text, style = ty.caption, color = c.textMuted)
            }
        } else {
            Text(cell.text, style = ty.caption, color = c.textMuted)
        }
    }
    val hiddenCell: @Composable (String) -> Unit = { word ->
        if (onHidden == null) Text(word, style = ty.caption, color = c.textMuted) else SbFactsLink(word, onHidden)
    }
    BoxWithConstraints(
        modifier
            .fillMaxWidth()
            .padding(horizontal = t.spacing.gutter)
            .semantics(mergeDescendants = true) { },
    ) {
        // D101 (11): every cell as the line draws it, its „·“ and 4 dp included, on one line
        val list = with(LocalDensity.current) {
            fun w(text: String) = measurer.measure(text, ty.caption, softWrap = false, maxLines = 1).size.width
            val dot = w("·") + t.space.s1.roundToPx()
            val icon = t.size.iconSm.roundToPx()
            val widths = buildList {
                if (stale) add(icon + t.space.s1.roundToPx() + w(notes.staleNotice ?: ""))
                shown.forEach { add(if (it.place) icon + t.space.s0_5.roundToPx() + w(it.text) else w(it.text)) }
                hiddenWord?.let { add(w(it)) }
                notes.demo?.let { add(w(it) + 2 * t.space.s2.roundToPx()) }
            }
            widths.any { dot + it > constraints.maxWidth }
        }
        if (list) {
            // 12 dp between the entries, clearly more than the step from line to line inside a cell, so a cell that
            // wraps inside reads as one entry (provisional, agent)
            Column(Modifier.fillMaxWidth(), verticalArrangement = Arrangement.spacedBy(t.space.s3)) {
                name(Modifier)
                if (stale) staleCell()
                shown.forEach { factCell(it) }
                hiddenWord?.let { hiddenCell(it) }
                notes.demo?.let { SbDemoMarker(it) }
            }
        } else {
            SbFlowRow(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
                name(Modifier.align(Alignment.CenterVertically))
                if (stale) SbFactsCell(centred = true) { staleCell() }
                // a cell moves to the next line whole
                shown.forEach { cell -> SbFactsCell { factCell(cell) } }
                hiddenWord?.let { word -> SbFactsCell { hiddenCell(word) } }
                notes.demo?.let { SbFactsCell { SbDemoMarker(it) } }
            }
        }
    }
}

/**
 * One cell of the facts line: the „·“ (hidden from TalkBack), 4 dp, the cell; centred on the line. The „·“ stands on
 * the baseline of the cell's first line, so a cell that wraps inside keeps it beside its first word (provisional,
 * agent); [centred] = centred on the whole cell instead, as the web's inline-flex cell of the stale notice.
 */
@Composable
private fun RowScope.SbFactsCell(modifier: Modifier = Modifier, centred: Boolean = false, content: @Composable () -> Unit) {
    Row(
        modifier.align(Alignment.CenterVertically),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(SebaroTheme.tokens.space.s1),
    ) {
        Text(
            "·",
            style = SebaroTheme.typography.caption,
            color = SebaroTheme.colors.textMuted,
            modifier = Modifier.clearAndSetSemantics { }.then(if (centred) Modifier else Modifier.alignByBaseline()),
        )
        Box(if (centred) Modifier else Modifier.alignByBaseline()) { content() }
    }
}

/** „n nicht belegt“ as a link to the full form: text colour, the 2 dp link underline, a 48 dp target, the focus ring. */
@Composable
private fun SbFactsLink(word: String, onClick: () -> Unit) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    Box(
        Modifier
            .sbFocusRing(interaction, t.radius.small)
            .heightIn(min = t.size.targetTouch)
            .clickable(interactionSource = interaction, indication = null, role = Role.Button, onClick = onClick),
        contentAlignment = Alignment.CenterStart,
    ) {
        Text(
            word,
            style = SebaroTheme.typography.caption,
            color = if (pressed || hovered) c.link else c.text,
            maxLines = 1,
            modifier = Modifier.sbLinkUnderline(),
        )
    }
}
